pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address funder, uint256 lockTime) public {
        vm.assume(funder != address(0));
        amount = bound(amount, 0, 1 ether);
        lockTime = bound(lockTime, 0, 1e18);
        vm.deal(funder, amount);

        // Adversarial counterparty: a log file contract whose AddMessage reverts.
        RevertLog log = new RevertLog();
        c.SetLogFile(address(log));

        vm.prank(funder);
        bool ok;
        try c.Put{value: amount}(lockTime) { ok = true; } catch { ok = false; }

        // The reference honors the configured log: since the log reverts, Put must revert.
        // The mutant stores the zero address (call to it succeeds), so Put succeeds and this fails.
        assertTrue(!ok);
    }
}

contract RevertLog {
    fallback() external payable { revert(); }
}

