pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 amount, uint256 minSum) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        minSum = bound(minSum, 0, 1e18);
        amount = bound(amount, minSum, minSum + 1e18);

        // adversarial log: AddMessage always reverts
        BadLog lg = new BadLog();

        // set the log file through SetLogFile
        vm.prank(caller);
        c.SetLogFile(address(lg));

        // configure minimum sum
        c.SetMinSum(minSum);

        // deposit via fallback (Put(0), zero lock time)
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool okPut, ) = address(c).call{value: amount}("");
        assertTrue(okPut);

        // unlock time has passed (lockTime 0)
        vm.warp(block.timestamp + 1);

        // Collect succeeds externally but the log's AddMessage reverts,
        // so the whole Collect must revert on the reference contract.
        vm.prank(caller);
        bool okCollect;
        try c.Collect(amount) { okCollect = true; } catch { okCollect = false; }
        assertTrue(!okCollect);
    }
}

contract BadLog {
    function AddMessage(address, uint256, string calldata) external pure {
        revert();
    }
}

