pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 1000 ether);

        // configure the log file with a logger whose AddMessage reverts
        RevertLog lg = new RevertLog();
        c.SetLogFile(address(lg));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // rule: after the log file is set to a reverting logger, ANY Put
        // (any actor, any amount) must revert; the mutant (zero-address log)
        // lets the Put succeed, breaking this for some input.
        assertTrue(!ok, "Put must revert when the configured log reverts");
    }
}

contract RevertLog {
    function AddMessage(address, uint, string calldata) external pure {
        revert("log rejected");
    }
}

