pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address log1, address log2, bool doInit) public {
        vm.assume(log1 != address(0));
        vm.assume(log2 != address(0));
        vm.assume(log1 != log2);

        vm.prank(address(this));
        c.SetLogFile(address(log1));
        address before = c.Log();

        if (doInit) {
            c.Initialized();
        }

        bool ok;
        vm.prank(address(this));
        try c.SetLogFile(log2) { ok = true; } catch { ok = false; }

        address after1 = c.Log();

        if (doInit) {
            // Once initialized, SetLogFile must revert and the log address must be unchanged.
            assertTrue(!ok && after1 == before);
        } else {
            // Before initialization, an explicit SetLogFile sets the log address.
            assertTrue(ok && after1 == log2);
        }
    }
}

